#!/usr/bin/env python3
"""daemonctl — create, install, inspect, repair and remove background daemons.

Standard library only. macOS (launchd), Linux (systemd --user), Windows (schtasks).

    daemonctl new <slug> --recipe rss-to-markdown --set feeds=https://... --set out_dir=~/Notes
    daemonctl install <slug>
    daemonctl verify <slug>
    daemonctl list
    daemonctl health
    daemonctl logs <slug> -n 40 --level error
    daemonctl pause <slug> / resume <slug>
    daemonctl uninstall <slug> --purge

Every command accepts --json for machine-readable output, which is what the
daemon-agent skill and its agents consume.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))

from daemon_runtime import (  # noqa: E402
    SCHEMA_VERSION, atomic_write_json, daemon_dir, daemons_dir, home,
    read_json, registry_path, utcnow,
)
import supervisors  # noqa: E402

RECIPES_DIR = HERE.parent / "recipes"
SLUG_RE = re.compile(r"^[a-z0-9][a-z0-9-]{1,48}[a-z0-9]$")

WORKER_HEADER = '''#!/usr/bin/env python3
"""{title}

Generated by daemon-agent. Edit freely; `daemonctl install` picks up changes.
Reinstall is only needed when the schedule or the mode changes.
"""

import os
import sys

sys.path.insert(0, os.path.join(
    os.path.expanduser(os.environ.get("DAEMON_AGENT_HOME", "~/.daemon-agent")), "lib"))

from daemon_runtime import run_once, serve  # noqa: E402
'''

BLANK_WORKER = WORKER_HEADER + '''

def main(ctx):
    """One pass of work.

    Raise on failure so the run is recorded as failed and retried.
    Return a small dict to have it recorded in the success log line.
    """
    ctx.log.info("hello from {slug}")
    return {{"ok": True}}


run_once(main)
'''

BLANK_SERVICE_WORKER = WORKER_HEADER + '''

def main(ctx):
    """One cycle of a long-lived daemon. Called repeatedly until stopped."""
    ctx.log.info("cycle")


serve(main, interval={interval})
'''


# --------------------------------------------------------------------------
# small helpers
# --------------------------------------------------------------------------

def die(message: str, as_json=False, code=1):
    if as_json:
        print(json.dumps({"ok": False, "error": message}, indent=2))
    else:
        sys.stderr.write("error: %s\n" % message)
    sys.exit(code)


def emit(payload, as_json: bool, text: str = None):
    if as_json:
        print(json.dumps(payload, indent=2, default=str))
    elif text is not None:
        print(text)


def parse_age(value) -> float:
    """Seconds since an ISO timestamp. inf when missing or unparseable."""
    if not value:
        return float("inf")
    try:
        stamp = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return float("inf")
    if stamp.tzinfo is None:
        stamp = stamp.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - stamp).total_seconds()


def human_age(seconds: float) -> str:
    if seconds == float("inf"):
        return "never"
    seconds = int(seconds)
    if seconds < 90:
        return "%ds ago" % seconds
    if seconds < 5400:
        return "%dm ago" % (seconds // 60)
    if seconds < 172800:
        return "%dh ago" % (seconds // 3600)
    return "%dd ago" % (seconds // 86400)


# --------------------------------------------------------------------------
# registry
# --------------------------------------------------------------------------

def load_registry() -> dict:
    reg = read_json(registry_path(), {})
    reg.setdefault("schema", SCHEMA_VERSION)
    reg.setdefault("daemons", {})
    return reg


def save_registry(reg) -> None:
    atomic_write_json(registry_path(), reg)


def register(manifest) -> None:
    reg = load_registry()
    reg["daemons"][manifest["slug"]] = {
        "name": manifest.get("name"),
        "description": manifest.get("description"),
        "mode": manifest["mode"],
        "interval_seconds": manifest.get("interval_seconds"),
        "recipe": manifest.get("recipe"),
        "supervisor": manifest.get("supervisor"),
        "unit_path": manifest.get("unit_path"),
        "installed_at": manifest.get("installed_at"),
        "enabled": manifest.get("enabled", True),
    }
    save_registry(reg)


def deregister(slug) -> None:
    reg = load_registry()
    reg["daemons"].pop(slug, None)
    save_registry(reg)


def load_manifest(slug, as_json=False) -> dict:
    path = daemon_dir(slug) / "manifest.json"
    manifest = read_json(path, {})
    if not manifest:
        die("no daemon named %r. `daemonctl list` shows what exists." % slug, as_json)
    return manifest


def save_manifest(manifest) -> None:
    atomic_write_json(daemon_dir(manifest["slug"]) / "manifest.json", manifest)


def sync_lib() -> Path:
    """Copy the runtime next to the daemons so workers do not depend on where
    the skill folder lives. A buyer can move or delete the plugin afterwards."""
    lib = home() / "lib"
    lib.mkdir(parents=True, exist_ok=True)
    shutil.copy2(str(HERE / "daemon_runtime.py"), str(lib / "daemon_runtime.py"))
    return lib


# --------------------------------------------------------------------------
# recipes
# --------------------------------------------------------------------------

def list_recipes() -> list:
    out = []
    if not RECIPES_DIR.exists():
        return out
    for path in sorted(RECIPES_DIR.iterdir()):
        meta_path = path / "recipe.json"
        if meta_path.exists():
            meta = read_json(meta_path, {})
            meta["id"] = path.name
            out.append(meta)
    return out


def load_recipe(name, as_json=False) -> dict:
    path = RECIPES_DIR / name
    meta = read_json(path / "recipe.json", {})
    if not meta:
        available = ", ".join(r["id"] for r in list_recipes()) or "none"
        die("unknown recipe %r. Available: %s" % (name, available), as_json)
    meta["id"] = name
    meta["_dir"] = path
    return meta


def coerce(value: str):
    """Turn a --set value into a real type: json first, then int/float/bool."""
    text = value.strip()
    lowered = text.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    if lowered in ("null", "none", ""):
        return None
    try:
        return json.loads(text)
    except ValueError:
        pass
    return text


def parse_sets(pairs) -> dict:
    config = {}
    for pair in pairs or []:
        if "=" not in pair:
            die("--set expects key=value, got %r" % pair)
        key, _, value = pair.partition("=")
        config[key.strip()] = coerce(value)
    return config


# --------------------------------------------------------------------------
# commands
# --------------------------------------------------------------------------

def cmd_new(args):
    slug = args.slug
    if not SLUG_RE.match(slug):
        die("slug must be lowercase letters, digits and hyphens, 3-50 chars", args.json)
    target = daemon_dir(slug)
    if target.exists() and not args.force:
        die("%s already exists. Use --force to overwrite its manifest." % target, args.json)

    recipe = load_recipe(args.recipe, args.json) if args.recipe else None
    config = dict((recipe or {}).get("defaults", {}))
    config.update(parse_sets(args.set))

    mode = args.mode or (recipe or {}).get("mode") or "interval"
    interval = args.interval or (recipe or {}).get("interval_seconds") or 300
    secrets = list((recipe or {}).get("secrets", []))

    missing = [k for k in (recipe or {}).get("required", []) if config.get(k) in (None, "")]
    if missing:
        die("recipe %r needs: %s (pass --set key=value)" % (args.recipe, ", ".join(missing)),
            args.json)

    (target / "logs").mkdir(parents=True, exist_ok=True)
    sync_lib()

    worker_path = target / "worker.py"
    if recipe:
        shutil.copy2(str(recipe["_dir"] / "worker.py"), str(worker_path))
    elif not worker_path.exists() or args.force:
        title = args.name or slug
        body = (BLANK_SERVICE_WORKER if mode == "service" else BLANK_WORKER)
        worker_path.write_text(
            body.format(title=title, slug=slug, interval=int(interval)), encoding="utf-8")
    os.chmod(str(worker_path), 0o755)

    manifest = {
        "schema": SCHEMA_VERSION,
        "slug": slug,
        "name": args.name or (recipe or {}).get("name") or slug,
        "description": args.description or (recipe or {}).get("description") or "",
        "recipe": args.recipe,
        "mode": mode,
        "interval_seconds": int(interval),
        "python": supervisors.python_executable(),
        "worker": str(worker_path),
        "working_dir": str(target),
        "stdout_log": str(target / "logs" / "stdout.log"),
        "stderr_log": str(target / "logs" / "stderr.log"),
        "label": "com.daemon-agent." + slug,
        "env": parse_sets(args.env),
        "secrets": secrets,
        "config": config,
        "restart_delay_seconds": 10,
        "created": utcnow(),
        "enabled": False,
    }
    save_manifest(manifest)
    payload = {"ok": True, "slug": slug, "dir": str(target),
               "worker": str(worker_path), "manifest": manifest}
    emit(payload, args.json,
         "created %s\n  worker:   %s\n  manifest: %s\n  next:     daemonctl install %s"
         % (slug, worker_path, target / "manifest.json", slug))


def cmd_install(args):
    manifest = load_manifest(args.slug, args.json)
    sync_lib()
    missing = [s for s in manifest.get("secrets", []) if not _secret_present(s)]
    if missing and not args.allow_missing_secrets:
        die("missing secrets: %s\n  set them with: daemonctl secret set <NAME> <value>\n"
            "  or install anyway with --allow-missing-secrets" % ", ".join(missing), args.json)

    sup = supervisors.detect()
    unit = sup.install(manifest)
    manifest["supervisor"] = sup.name
    manifest["unit_path"] = str(unit)
    manifest["installed_at"] = utcnow()
    manifest["enabled"] = True
    save_manifest(manifest)
    register(manifest)
    status = sup.status(manifest)
    payload = {"ok": True, "slug": manifest["slug"], "supervisor": sup.name,
               "unit": str(unit), "status": status}
    emit(payload, args.json,
         "installed %s under %s\n  unit:   %s\n  status: %s\n  next:   daemonctl verify %s"
         % (manifest["slug"], sup.name, unit, status.get("detail"), manifest["slug"]))


def cmd_uninstall(args):
    manifest = load_manifest(args.slug, args.json)
    sup = supervisors.detect()
    sup.uninstall(manifest)
    deregister(manifest["slug"])
    removed_dir = False
    if args.purge:
        shutil.rmtree(str(daemon_dir(manifest["slug"])), ignore_errors=True)
        removed_dir = True
    else:
        manifest["enabled"] = False
        manifest["unit_path"] = None
        save_manifest(manifest)
    payload = {"ok": True, "slug": manifest["slug"], "purged": removed_dir}
    emit(payload, args.json,
         "uninstalled %s%s" % (manifest["slug"],
                               " and deleted its directory" if removed_dir else
                               " (files kept in %s)" % daemon_dir(manifest["slug"])))


def cmd_pause(args):
    manifest = load_manifest(args.slug, args.json)
    supervisors.detect().stop(manifest)
    manifest["enabled"] = False
    save_manifest(manifest)
    register(manifest)
    emit({"ok": True, "slug": manifest["slug"], "enabled": False}, args.json,
         "paused %s" % manifest["slug"])


def cmd_resume(args):
    manifest = load_manifest(args.slug, args.json)
    supervisors.detect().start(manifest)
    manifest["enabled"] = True
    save_manifest(manifest)
    register(manifest)
    emit({"ok": True, "slug": manifest["slug"], "enabled": True}, args.json,
         "resumed %s" % manifest["slug"])


def cmd_kick(args):
    manifest = load_manifest(args.slug, args.json)
    supervisors.detect().kick(manifest)
    emit({"ok": True, "slug": manifest["slug"]}, args.json,
         "asked the supervisor to run %s now" % manifest["slug"])


def cmd_run_once(args):
    """Run the worker in the foreground, exactly as the supervisor would."""
    manifest = load_manifest(args.slug, args.json)
    sync_lib()
    env = dict(os.environ)
    env.update(supervisors.detect().env_block(manifest))
    cmd = [manifest["python"], manifest["worker"], "--slug", manifest["slug"], "--echo"]
    proc = subprocess.run(cmd, cwd=manifest["working_dir"], env=env,
                          capture_output=True, text=True, timeout=args.timeout)
    payload = {"ok": proc.returncode == 0, "exit_code": proc.returncode,
               "stdout": proc.stdout, "stderr": proc.stderr}
    if args.json:
        print(json.dumps(payload, indent=2))
    else:
        if proc.stdout.strip():
            print(proc.stdout.rstrip())
        if proc.stderr.strip():
            print(proc.stderr.rstrip())
        print("exit code: %d" % proc.returncode)
    sys.exit(0 if proc.returncode == 0 else 1)


def _health_of(manifest) -> dict:
    slug = manifest["slug"]
    beat = read_json(daemon_dir(slug) / "heartbeat.json", {})
    try:
        sup = supervisors.detect()
        status = sup.status(manifest)
    except supervisors.SupervisorError as exc:
        status = {"loaded": False, "running": False, "last_exit": None,
                  "detail": str(exc)}

    interval = int(manifest.get("interval_seconds") or 300)
    grace = int(manifest.get("health", {}).get("max_silence_seconds")
                or max(interval * 3 + 60, 180))
    success_age = parse_age(beat.get("last_success"))
    error_age = parse_age(beat.get("last_error"))

    if not manifest.get("enabled", False):
        verdict, reason = "paused", "paused by operator"
    elif not status.get("loaded"):
        verdict, reason = "failed", "not loaded in %s" % (manifest.get("supervisor") or "supervisor")
    elif manifest["mode"] == "service" and not status.get("running"):
        verdict, reason = "failed", "service is not running"
    elif success_age == float("inf") and error_age == float("inf"):
        verdict, reason = "unknown", "has never reported a run yet"
    elif error_age < success_age:
        verdict, reason = "degraded", "last run failed: %s" % (
            beat.get("last_error_message") or "see logs")
    elif success_age > grace:
        verdict, reason = "stalled", "no successful run for %s (grace %ds)" % (
            human_age(success_age), grace)
    else:
        verdict, reason = "healthy", "last success %s" % human_age(success_age)

    return {
        "slug": slug,
        "name": manifest.get("name"),
        "verdict": verdict,
        "reason": reason,
        "mode": manifest["mode"],
        "interval_seconds": interval,
        "enabled": manifest.get("enabled", False),
        "supervisor": status,
        "runs": beat.get("runs", 0),
        "failures": beat.get("failures", 0),
        "last_success": beat.get("last_success"),
        "last_success_age_s": None if success_age == float("inf") else round(success_age),
        "last_error": beat.get("last_error"),
        "last_error_message": beat.get("last_error_message"),
        "last_duration_s": beat.get("last_duration_s"),
    }


def _all_manifests() -> list:
    out = []
    if not daemons_dir().exists():
        return out
    for path in sorted(daemons_dir().iterdir()):
        manifest = read_json(path / "manifest.json", {})
        if manifest:
            out.append(manifest)
    return out


def cmd_list(args):
    rows = [{
        "slug": m["slug"], "name": m.get("name"), "mode": m["mode"],
        "interval_seconds": m.get("interval_seconds"),
        "enabled": m.get("enabled", False), "recipe": m.get("recipe"),
        "description": m.get("description"),
    } for m in _all_manifests()]
    if args.json:
        print(json.dumps({"ok": True, "daemons": rows}, indent=2))
        return
    if not rows:
        print("no daemons yet. `daemonctl recipes` shows what ships in the box.")
        return
    width = max(len(r["slug"]) for r in rows)
    for row in rows:
        schedule = ("every %ds" % row["interval_seconds"]) if row["mode"] == "interval" \
            else "always on"
        print("%-*s  %-9s  %-12s  %s" % (
            width, row["slug"], "enabled" if row["enabled"] else "paused",
            schedule, row.get("description") or ""))


def cmd_status(args):
    manifest = load_manifest(args.slug, args.json)
    health = _health_of(manifest)
    if args.json:
        print(json.dumps({"ok": True, "health": health, "manifest": manifest}, indent=2))
        return
    print("%s  [%s]" % (health["slug"], health["verdict"]))
    print("  reason:      %s" % health["reason"])
    print("  mode:        %s%s" % (health["mode"],
                                   "" if health["mode"] == "service"
                                   else " every %ds" % health["interval_seconds"]))
    print("  supervisor:  %s" % health["supervisor"].get("detail"))
    print("  runs:        %s ok-ish / %s failures" % (health["runs"], health["failures"]))
    print("  last ok:     %s" % (health["last_success"] or "never"))
    if health["last_error_message"]:
        print("  last error:  %s" % health["last_error_message"])
    print("  dir:         %s" % daemon_dir(health["slug"]))


def cmd_health(args):
    manifests = _all_manifests()
    if args.slug:
        manifests = [m for m in manifests if m["slug"] == args.slug]
    results = [_health_of(m) for m in manifests]
    order = {"failed": 0, "stalled": 1, "degraded": 2, "unknown": 3, "paused": 4, "healthy": 5}
    results.sort(key=lambda r: (order.get(r["verdict"], 9), r["slug"]))
    summary = {}
    for row in results:
        summary[row["verdict"]] = summary.get(row["verdict"], 0) + 1
    bad = [r for r in results if r["verdict"] in ("failed", "stalled", "degraded")]
    if args.json:
        print(json.dumps({"ok": not bad, "summary": summary, "daemons": results}, indent=2))
    else:
        if not results:
            print("no daemons installed")
        for row in results:
            print("%-9s %-24s %s" % (row["verdict"], row["slug"], row["reason"]))
        if summary:
            print("\n" + "  ".join("%s: %d" % (k, v) for k, v in sorted(summary.items())))
    sys.exit(1 if bad and args.strict else 0)


def cmd_logs(args):
    manifest = load_manifest(args.slug, args.json)
    path = daemon_dir(manifest["slug"]) / "logs" / "daemon.log"
    if args.stderr:
        path = Path(manifest["stderr_log"])
    if not path.exists():
        die("no log yet at %s (has it run?)" % path, args.json)

    def matching(lines):
        for line in lines:
            line = line.rstrip("\n")
            if not line:
                continue
            if args.level or args.grep:
                try:
                    record = json.loads(line)
                except ValueError:
                    record = {"msg": line, "level": "raw"}
                if args.level and record.get("level") != args.level:
                    continue
                if args.grep and args.grep.lower() not in line.lower():
                    continue
            yield line

    if args.follow:
        with open(str(path), "r", encoding="utf-8", errors="replace") as fh:
            fh.seek(0, os.SEEK_END)
            try:
                while True:
                    line = fh.readline()
                    if not line:
                        time.sleep(0.4)
                        continue
                    for out in matching([line]):
                        print(_format_log(out, args.json))
            except KeyboardInterrupt:
                return
        return

    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    selected = list(matching(lines))[-args.number:]
    if args.json:
        records = []
        for line in selected:
            try:
                records.append(json.loads(line))
            except ValueError:
                records.append({"raw": line})
        print(json.dumps({"ok": True, "slug": manifest["slug"], "lines": records}, indent=2))
        return
    for line in selected:
        print(_format_log(line, False))


def _format_log(line, as_json):
    if as_json:
        return line
    try:
        record = json.loads(line)
    except ValueError:
        return line
    extras = {k: v for k, v in record.items()
              if k not in ("ts", "level", "daemon", "msg") and v is not None}
    tail = ("  " + json.dumps(extras, default=str)) if extras else ""
    return "%s %-5s %s%s" % (record.get("ts", ""), record.get("level", ""),
                             record.get("msg", ""), tail)


def cmd_verify(args):
    """The acceptance gate: run it for real and prove the supervisor saw it.

    A daemon that installs cleanly and never runs is the single most common
    silent failure, so `verify` refuses to pass on a plist alone.
    """
    manifest = load_manifest(args.slug, args.json)
    checks = []

    def check(name, ok, detail=""):
        checks.append({"check": name, "ok": bool(ok), "detail": str(detail)})
        return ok

    sup = supervisors.detect()
    status = sup.status(manifest)
    check("supervisor loaded", status.get("loaded"), status.get("detail"))

    before = read_json(daemon_dir(manifest["slug"]) / "heartbeat.json", {})
    baseline = before.get("last_success")

    if manifest["mode"] == "interval":
        try:
            sup.kick(manifest)
            check("forced run accepted", True, "kickstarted")
        except supervisors.SupervisorError as exc:
            check("forced run accepted", False, str(exc))
    else:
        check("service running", status.get("running"), status.get("detail"))

    deadline = time.time() + args.timeout
    beat = before
    while time.time() < deadline:
        beat = read_json(daemon_dir(manifest["slug"]) / "heartbeat.json", {})
        if beat.get("last_success") and beat.get("last_success") != baseline:
            break
        if beat.get("last_error") and beat.get("last_error") != before.get("last_error"):
            break
        time.sleep(1)

    fresh_success = bool(beat.get("last_success")) and beat.get("last_success") != baseline
    check("worker reported a successful run", fresh_success,
          beat.get("last_success") or "no new heartbeat within %ds" % args.timeout)
    if beat.get("last_error") and beat.get("last_error") != before.get("last_error"):
        check("no new error", False, beat.get("last_error_message") or "see logs")

    log_path = daemon_dir(manifest["slug"]) / "logs" / "daemon.log"
    check("wrote a log line", log_path.exists() and log_path.stat().st_size > 0, str(log_path))

    health = _health_of(manifest)
    check("health verdict is healthy", health["verdict"] == "healthy",
          "%s: %s" % (health["verdict"], health["reason"]))

    ok = all(c["ok"] for c in checks)
    payload = {"ok": ok, "slug": manifest["slug"], "checks": checks, "health": health}
    if args.json:
        print(json.dumps(payload, indent=2))
    else:
        for c in checks:
            print("%s %s%s" % ("PASS" if c["ok"] else "FAIL", c["check"],
                               ("  -> " + c["detail"]) if c["detail"] else ""))
        print("\n%s" % ("VERIFIED" if ok else "NOT VERIFIED"))
        if not ok:
            print("run `daemonctl doctor %s` for the likely cause" % manifest["slug"])
    sys.exit(0 if ok else 1)


def cmd_doctor(args):
    """Diagnose one daemon against the failure modes that actually happen."""
    manifest = load_manifest(args.slug, args.json)
    findings = []

    def note(severity, issue, fix):
        findings.append({"severity": severity, "issue": issue, "fix": fix})

    worker = Path(manifest["worker"])
    if not worker.exists():
        note("critical", "worker.py is missing at %s" % worker,
             "restore it or run `daemonctl new %s --recipe ... --force`" % manifest["slug"])
    python = Path(manifest["python"])
    if not python.exists():
        note("critical", "the interpreter baked into the unit is gone: %s" % python,
             "run `daemonctl repair %s` to repoint at %s"
             % (manifest["slug"], supervisors.python_executable()))
    lib = home() / "lib" / "daemon_runtime.py"
    if not lib.exists():
        note("critical", "daemon_runtime.py missing from %s" % lib.parent,
             "run `daemonctl install %s` which re-syncs the runtime" % manifest["slug"])

    for name in manifest.get("secrets", []):
        if not _secret_present(name):
            note("critical", "secret %s is not set" % name,
                 "daemonctl secret set %s <value>" % name)

    try:
        sup = supervisors.detect()
        status = sup.status(manifest)
        if not status.get("loaded"):
            note("critical", "not loaded in %s" % sup.name,
                 "daemonctl install %s" % manifest["slug"])
        if status.get("last_exit") not in (None, 0):
            note("warning", "last exit code was %s" % status.get("last_exit"),
                 "daemonctl logs %s --level error" % manifest["slug"])
    except supervisors.SupervisorError as exc:
        note("critical", "supervisor unavailable: %s" % exc, "see references/supervisors.md")

    stderr = Path(manifest["stderr_log"])
    if stderr.exists() and stderr.stat().st_size > 0:
        tail = stderr.read_text(encoding="utf-8", errors="replace").strip().splitlines()[-5:]
        blob = "\n".join(tail)
        if "ModuleNotFoundError" in blob:
            note("critical", "worker imports a module the daemon's interpreter lacks:\n%s" % blob,
                 "either drop the dependency (stdlib only is the house rule) or point "
                 "manifest.python at a venv interpreter that has it, then reinstall")
        elif "Permission denied" in blob or "Operation not permitted" in blob:
            note("critical", "permission error:\n%s" % blob,
                 "on macOS grant Full Disk Access to the interpreter in System Settings > "
                 "Privacy & Security, then `daemonctl install %s`" % manifest["slug"])
        elif blob:
            note("warning", "stderr is not empty:\n%s" % blob,
                 "daemonctl logs %s --stderr" % manifest["slug"])

    health = _health_of(manifest)
    if health["verdict"] == "stalled":
        note("warning", health["reason"],
             "check the source is actually producing events, then `daemonctl kick %s`"
             % manifest["slug"])

    payload = {"ok": not any(f["severity"] == "critical" for f in findings),
               "slug": manifest["slug"], "health": health, "findings": findings}
    if args.json:
        print(json.dumps(payload, indent=2))
    else:
        print("%s  [%s] %s" % (manifest["slug"], health["verdict"], health["reason"]))
        if not findings:
            print("no problems found")
        for f in findings:
            print("\n%s: %s\n  fix: %s" % (f["severity"].upper(), f["issue"], f["fix"]))
    sys.exit(0 if payload["ok"] else 1)


def cmd_repair(args):
    """Repoint a daemon at the current interpreter and reinstall its unit."""
    manifest = load_manifest(args.slug, args.json)
    manifest["python"] = supervisors.python_executable()
    manifest["worker"] = str(daemon_dir(manifest["slug"]) / "worker.py")
    manifest["working_dir"] = str(daemon_dir(manifest["slug"]))
    manifest["stdout_log"] = str(daemon_dir(manifest["slug"]) / "logs" / "stdout.log")
    manifest["stderr_log"] = str(daemon_dir(manifest["slug"]) / "logs" / "stderr.log")
    save_manifest(manifest)
    sync_lib()
    sup = supervisors.detect()
    unit = sup.install(manifest)
    manifest["supervisor"] = sup.name
    manifest["unit_path"] = str(unit)
    manifest["enabled"] = True
    save_manifest(manifest)
    register(manifest)
    emit({"ok": True, "slug": manifest["slug"], "python": manifest["python"],
          "unit": str(unit)}, args.json,
         "repaired %s (interpreter %s)" % (manifest["slug"], manifest["python"]))


def cmd_recipes(args):
    recipes = list_recipes()
    if args.json:
        print(json.dumps({"ok": True, "recipes": recipes}, indent=2))
        return
    for recipe in recipes:
        print("%-22s %s" % (recipe["id"], recipe.get("description", "")))
        if recipe.get("required"):
            print("%-22s required: %s" % ("", ", ".join(recipe["required"])))
        if recipe.get("secrets"):
            print("%-22s secrets:  %s" % ("", ", ".join(recipe["secrets"])))


def cmd_show(args):
    manifest = load_manifest(args.slug, args.json)
    if args.command:
        sup = supervisors.detect()
        print(" ".join(sup.program_args(manifest)))
        return
    if args.worker:
        print(Path(manifest["worker"]).read_text(encoding="utf-8"))
        return
    if args.unit and manifest.get("unit_path"):
        print(Path(manifest["unit_path"]).read_text(encoding="utf-8", errors="replace"))
        return
    print(json.dumps(manifest, indent=2))


def cmd_set(args):
    """Change config on a live daemon without regenerating it."""
    manifest = load_manifest(args.slug, args.json)
    updates = parse_sets(args.set)
    manifest.setdefault("config", {}).update(updates)
    reinstall_needed = False
    if args.interval:
        manifest["interval_seconds"] = int(args.interval)
        reinstall_needed = True
    save_manifest(manifest)
    if reinstall_needed and manifest.get("enabled"):
        sup = supervisors.detect()
        manifest["unit_path"] = str(sup.install(manifest))
        save_manifest(manifest)
    emit({"ok": True, "slug": manifest["slug"], "config": manifest["config"],
          "reinstalled": reinstall_needed}, args.json,
         "updated %s%s" % (manifest["slug"], " and reinstalled its unit"
                           if reinstall_needed else ""))


# --------------------------------------------------------------------------
# secrets
# --------------------------------------------------------------------------

def _secrets_file() -> Path:
    return home() / "secrets.env"


def _secret_present(name) -> bool:
    if os.environ.get(name):
        return True
    sys.path.insert(0, str(HERE))
    from daemon_runtime import get_secret
    try:
        return bool(get_secret(name, required=False))
    except Exception:
        return False


def cmd_secret(args):
    path = _secrets_file()
    if args.action == "list":
        names = []
        if path.exists():
            for line in path.read_text(encoding="utf-8").splitlines():
                if "=" in line and not line.strip().startswith("#"):
                    names.append(line.split("=", 1)[0].strip())
        emit({"ok": True, "names": names, "file": str(path)}, args.json,
             "\n".join(names) or "no secrets stored in %s" % path)
        return
    if args.action == "set":
        if not args.value:
            die("usage: daemonctl secret set NAME VALUE", args.json)
        lines = []
        if path.exists():
            lines = [l for l in path.read_text(encoding="utf-8").splitlines()
                     if not l.startswith(args.name + "=")]
        lines.append("%s=%s" % (args.name, args.value))
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        os.chmod(str(path), 0o600)
        emit({"ok": True, "name": args.name, "file": str(path)}, args.json,
             "stored %s in %s (mode 600)" % (args.name, path))
        return
    if args.action == "rm":
        if path.exists():
            lines = [l for l in path.read_text(encoding="utf-8").splitlines()
                     if not l.startswith(args.name + "=")]
            path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        emit({"ok": True, "name": args.name}, args.json, "removed %s" % args.name)


# --------------------------------------------------------------------------
# argparse
# --------------------------------------------------------------------------

def build_parser():
    parser = argparse.ArgumentParser(
        prog="daemonctl", description="create and supervise background daemons")
    parser.add_argument("--json", action="store_true", help="machine-readable output")

    # --json has to work on both sides of the subcommand, because that is where
    # people and agents actually type it. SUPPRESS stops the subparser default
    # from clobbering a --json given before the subcommand.
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--json", action="store_true", default=argparse.SUPPRESS,
                        help="machine-readable output")

    sub = parser.add_subparsers(dest="command", required=True)
    _original = sub.add_parser

    def add_parser(name, **kw):
        kw.setdefault("parents", [common])
        return _original(name, **kw)

    sub.add_parser = add_parser

    p = sub.add_parser("new", help="scaffold a new daemon")
    p.add_argument("slug")
    p.add_argument("--recipe")
    p.add_argument("--name")
    p.add_argument("--description")
    p.add_argument("--mode", choices=["interval", "service"])
    p.add_argument("--interval", type=int, help="seconds between runs")
    p.add_argument("--set", action="append", metavar="KEY=VALUE")
    p.add_argument("--env", action="append", metavar="KEY=VALUE")
    p.add_argument("--force", action="store_true")
    p.set_defaults(func=cmd_new)

    p = sub.add_parser("install", help="write the OS unit and load it")
    p.add_argument("slug")
    p.add_argument("--allow-missing-secrets", action="store_true")
    p.set_defaults(func=cmd_install)

    p = sub.add_parser("uninstall", help="unload and remove the OS unit")
    p.add_argument("slug")
    p.add_argument("--purge", action="store_true", help="also delete state and logs")
    p.set_defaults(func=cmd_uninstall)

    for name, fn, helptext in (("pause", cmd_pause, "stop without deleting"),
                               ("resume", cmd_resume, "start a paused daemon"),
                               ("kick", cmd_kick, "run now, outside the schedule")):
        p = sub.add_parser(name, help=helptext)
        p.add_argument("slug")
        p.set_defaults(func=fn)

    p = sub.add_parser("run-once", help="run the worker in the foreground")
    p.add_argument("slug")
    p.add_argument("--timeout", type=int, default=120)
    p.set_defaults(func=cmd_run_once)

    p = sub.add_parser("list", help="every daemon on this machine")
    p.set_defaults(func=cmd_list)

    p = sub.add_parser("status", help="one daemon in detail")
    p.add_argument("slug")
    p.set_defaults(func=cmd_status)

    p = sub.add_parser("health", help="verdict for every daemon")
    p.add_argument("--slug")
    p.add_argument("--strict", action="store_true", help="exit 1 when anything is unwell")
    p.set_defaults(func=cmd_health)

    p = sub.add_parser("logs", help="tail the structured log")
    p.add_argument("slug")
    p.add_argument("-n", "--number", type=int, default=30)
    p.add_argument("--level", choices=["debug", "info", "warn", "error"])
    p.add_argument("--grep")
    p.add_argument("--follow", action="store_true")
    p.add_argument("--stderr", action="store_true", help="raw stderr instead of the JSONL log")
    p.set_defaults(func=cmd_logs)

    p = sub.add_parser("verify", help="prove the daemon actually runs")
    p.add_argument("slug")
    p.add_argument("--timeout", type=int, default=60)
    p.set_defaults(func=cmd_verify)

    p = sub.add_parser("doctor", help="diagnose a daemon that is not working")
    p.add_argument("slug")
    p.set_defaults(func=cmd_doctor)

    p = sub.add_parser("repair", help="repoint at the current interpreter and reinstall")
    p.add_argument("slug")
    p.set_defaults(func=cmd_repair)

    p = sub.add_parser("recipes", help="list bundled recipes")
    p.set_defaults(func=cmd_recipes)

    p = sub.add_parser("show", help="print the manifest, worker or unit file")
    p.add_argument("slug")
    p.add_argument("--worker", action="store_true")
    p.add_argument("--unit", action="store_true")
    p.add_argument("--command", action="store_true", help="the exact command the OS runs")
    p.set_defaults(func=cmd_show)

    p = sub.add_parser("set", help="update config on an existing daemon")
    p.add_argument("slug")
    p.add_argument("--set", action="append", metavar="KEY=VALUE")
    p.add_argument("--interval", type=int)
    p.set_defaults(func=cmd_set)

    p = sub.add_parser("secret", help="store credentials outside the unit file")
    p.add_argument("action", choices=["set", "list", "rm"])
    p.add_argument("name", nargs="?")
    p.add_argument("value", nargs="?")
    p.set_defaults(func=cmd_secret)

    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        args.func(args)
    except supervisors.SupervisorError as exc:
        die(str(exc), getattr(args, "json", False))
    except KeyboardInterrupt:
        sys.exit(130)


if __name__ == "__main__":
    main()
